UPDATE articulos a SET contenido=(SELECT string_agg(coalesce(v.texto,substring(a.contenido from v.inicio for v.largo)),'' ORDER BY v.orden) FROM (VALUES (0, 1, 34, NULL::text),(1,0,0,E'<thead><tr><th scope="col">Condición de aceptación del sistema o componente mecánico</th><th scope="col">Cumple</th><th scope="col">No cumple</th><th scope="col">N/A*</th></tr></thead>'),(2, 35, 7, NULL::text),(3, 163, 23, NULL::text),(4,0,0,E'<td colspan="3">'),(5, 190, 36, NULL::text),(6,0,0,E'a) Los parabrisas deben estar libres de grietas que atraviesen ambas capas de vidrio, grietas entrecruzadas, despostillados en forma de estrella con un diámetro mayor a 12 mm (1/2") en la superficie barrida por los limpiaparabrisas.'),(7, 463, 271, NULL::text),(8,0,0,E'c) Los parabrisas deben estar exentos de entintado (polarizado) que baje 75 mm (3") desde la parte superior del parabrisas, no estar obstruidos en la superficie barrida por los limpiaparabrisas o en una superficie que pueda obstruir la vista de la carretera o de una intersección.'),(9, 1019, 225, NULL::text)) v(orden,inicio,largo,texto)) WHERE a.id='3572b50b-dfe6-531b-bca6-a4fe83866cdd' AND md5(a.contenido)='efbb3b2fd64663131847a6781878e821' RETURNING a.id,md5(a.contenido) hash;